import { BrowserRouter, Routes, Route, Link, useLocation } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { WalletProvider } from './contexts/WalletContext';
import JingPage from './pages/JingPage';
import DianPage from './pages/DianPage';
import YuanPage from './pages/YuanPage';
import JingCompPage from './pages/JingCompPage';
import WalletBar from './components/WalletBar';

function AnimatedRoute({ children }) {
  const location = useLocation();
  const [displayLocation, setDisplayLocation] = useState(location);
  const [show, setShow] = useState(true);

  useEffect(() => {
    setShow(false);
    const timer = setTimeout(() => {
      setDisplayLocation(location);
      setShow(true);
    }, 200);
    return () => clearTimeout(timer);
  }, [location]);

  return (
    <div
      className="transition-all duration-400 ease-out"
      style={{ opacity: show ? 1 : 0, transform: `translateY(${show ? 0 : 8}px)` }}
    >
      {children(displayLocation)}
    </div>
  );
}

function NavLink({ to, children }) {
  const location = useLocation();
  const isActive = location.pathname === to;
  return (
    <Link
      to={to}
      className={`transition-all duration-300 relative group ${
        isActive ? 'text-white' : 'text-neutral-400 hover:text-neutral-200'
      }`}
    >
      {children}
      <span
        className="absolute -bottom-0.5 left-0 h-px bg-emerald-500 transition-all duration-500"
        style={{ width: isActive ? '100%' : '0%' }}
      />
    </Link>
  );
}

function App() {
  return (
    <WalletProvider>
      <BrowserRouter>
        <div className="min-h-screen bg-neutral-950 text-white">
          <nav className="border-b border-neutral-800 px-6 py-3 flex items-center gap-6">
            <span className="font-bold text-lg tracking-wider text-emerald-400">ECHO</span>
            <NavLink to="/jing">境</NavLink>
            <NavLink to="/dian">典</NavLink>
            <NavLink to="/yuan">源</NavLink>
            <NavLink to="/jing-comp">竞</NavLink>
            <div className="ml-auto"><WalletBar /></div>
          </nav>
          <AnimatedRoute>
            {(loc) => (
              <Routes location={loc}>
                <Route path="/jing" element={<JingPage />} />
                <Route path="/dian" element={<DianPage />} />
                <Route path="/yuan" element={<YuanPage />} />
                <Route path="/jing-comp" element={<JingCompPage />} />
                <Route path="*" element={<JingPage />} />
              </Routes>
            )}
          </AnimatedRoute>
        </div>
      </BrowserRouter>
    </WalletProvider>
  );
}

export default App;

import { useState, useEffect } from 'react';
import { useWalletContext } from '../contexts/WalletContext';

export default function WalletBar() {
  const { address, balance, connecting, connect, disconnect, isConnected } = useWalletContext();
  const [visible, setVisible] = useState(false);

  // 纳相：连接时渐显，断开时渐隐
  useEffect(() => {
