  return (
    <div
      className="flex items-center gap-3 transition-all duration-500 ease-out"
      style={{ opacity: visible ? 1 : 0, transform: `translateY(${visible ? 0 : -4}px)` }}
    >
      {isConnected ? (
        <>
          <span className="text-sm text-neutral-400 transition-colors duration-300">{balance?.toFixed(4)} MEER</span>
          <span className="font-mono text-sm transition-all duration-300 hover:text-emerald-400">{address?.slice(0,6)}…{address?.slice(-4)}</span>
          <button
            onClick={disconnect}
            className="text-xs bg-neutral-800 px-2 py-1 rounded transition-all duration-300 hover:bg-neutral-700 hover:scale-105 active:scale-95"
          >断开</button>
        </>
      ) : (
        <button
