```PLAIN_TEXT
// src/utils/versionCompat.js
// ECHO 协议 — 边版本约束兼容性检查

function parseVersion(version) {
 if (!version || typeof version !== 'string') return [0, 0, 0];
 const parts = version.replace(/^v/i, '').split('.').map(Number);
 return [
 Number.isFinite(parts[0]) ? parts[0] : 0,
 Number.isFinite(parts[1]) ? parts[1] : 0,
 Number.isFinite(parts[2]) ? parts[2] : 0,
 ];
}

function compareVersion(a, b) {
 const av = parseVersion(a);
 const bv = parseVersion(b);
 for (let i = 0; i < 3; i++) {
 if (av[i] !== bv[i]) return av[i] > bv[i] ? 1 : -1;
 }
 return 0;
}

export function checkVersionCompatibility(currentVersion, constraint) {
 if (!currentVersion || !constraint) {
 return { compatible: false, reason: '版本或约束缺失' };
 }
 const cv = parseVersion(currentVersion);
 if (cv.every(v => v === 0) && currentVersion !== '0.0.0') {
 return { compatible: false, reason: `无法解析当前版本: ${currentVersion}` };
 }
 const { minVersion, maxVersion, constraintType = 'range' } = constraint;
 switch (constraintType) {
 case 'exact': {
 const exact = compareVersion(currentVersion, minVersion || maxVersion);
 return exact === 0
 ? { compatible: true, reason: null }
 : { compatible: false, reason: `要求精确版本 ${minVersion || maxVersion}，当前 ${currentVersion}` };
 }
 case 'min-only': {
 if (!minVersion) return { compatible: false, reason: 'min-only 约束缺少 minVersion' };
 const cmp = compareVersion(currentVersion, minVersion);
 return cmp >= 0
 ? { compatible: true, reason: null }
 : { compatible: false, reason: `要求最低版本 ${minVersion}，当前 ${currentVersion}` };
 }
 case 'max-only': {
 if (!maxVersion) return { compatible: false, reason: 'max-only 约束缺少 maxVersion' };
 const cmp = compareVersion(currentVersion, maxVersion);
 return cmp <= 0
 ? { compatible: true, reason: null }
 : { compatible: false, reason: `要求最高版本 ${maxVersion}，当前 ${currentVersion}` };
 }
 case 'range':
 default: {
 if (!minVersion || !maxVersion) {
 return { compatible: false, reason: 'range 约束需要 minVersion 和 maxVersion' };
 }
 const minOk = compareVersion(currentVersion, minVersion) >= 0;
 const maxOk = compareVersion(currentVersion, maxVersion) <= 0;
 if (minOk && maxOk) return { compatible: true, reason: null };
 if (!minOk) return { compatible: false, reason: `要求最低版本 ${minVersion}，当前 ${currentVersion}` };
 if (!maxOk) return { compatible: false, reason: `要求最高版本 ${maxVersion}，当前 ${currentVersion}` };
 }
 }
}

export const ALPHA_7_CONSTRAINT = {
 minVersion: '1.0.0',
 maxVersion: '2.0.0',
 constraintType: 'range',
 declaredAtBlock: 2704473,
 label: 'ALPHA-7 边伦理承诺',
 description: '节点间衍生关系需声明版本兼容范围，超出范围视为伦理越界',
};

export function checkAlpha7Compatibility(currentVersion) {
 return checkVersionCompatibility(currentVersion, ALPHA_7_CONSTRAINT);
}
